/**
 * AppShell.UserCard: the rail’s foot, showing the signed-in user.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Avatar from '../structure/Avatar'

export interface AppShellUserCardProps {
  /**
   * The first line. Initials and the identity colour are derived from it.
   */
  name: string
  /**
   * The second line, such as an email, a role or the signed-in workspace.
   */
  detail: string
  /**
   * The avatar image.
   */
  src?: string
  /**
   * The control at the row’s end, by convention a Menu, hidden when collapsed.
   */
  end?: JSX.Element
}

/** AppShell.UserCard: the rail’s foot, showing the signed-in user. */
export default function AppShellUserCard(given: AppShellUserCardProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const endSlot = resolveSlot(() => props.end)
    return (
      <div class={styles.userCard}>
        <Avatar name={props.name} src={props.src} size="md" />
        {/* userText */}
        <span class={styles.userText}>
          <span class={styles.userName}>{props.name}</span>
          <span class={styles.userDetail}>{props.detail}</span>
        </span>
        {endSlot.filled() ? <span class={styles.userEnd}>{endSlot()}</span> : null}
      </div>
    )
  })
}
